  // request capture (bodies included) — no console wrapping this time
  window.__reqs = [];
  const origSend = XMLHttpRequest.prototype.send, origOpen = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function(m, u, ...rest) { this.__url = String(u); this.__m = m; return origOpen.call(this, m, u, ...rest); };
  XMLHttpRequest.prototype.send = function(body) {
    const entry = {m: this.__m, url: this.__url.replace('http://localhost:3000',''), body: typeof body === 'string' ? body.slice(0, 600) : (body ? '<' + (body.constructor?.name || 'binary') + '>' : null)};
    this.addEventListener('loadend', () => { entry.status = this.status; entry.resp = String(this.responseText || '').slice(0, 300); });
    window.__reqs.push(entry);
    return origSend.call(this, body);
  };
  const of = window.fetch.bind(window);
  window.fetch = async (input, init) => {
    const entry = {m: init?.method || 'GET', url: String(input?.url || input).slice(0, 150), body: typeof init?.body === 'string' ? init.body.slice(0, 600) : (init?.body ? '<' + (init.body.constructor?.name || 'binary') + '>' : null), via: 'fetch'};
    window.__reqs.push(entry);
    const r = await of(input, init);
    entry.status = r.status;
    return r;
  };
  const ext = Array.from(document.querySelectorAll('input[type="radio"]')).find(x => x.value === 'external');
  ext.click();
  return new Promise(r => setTimeout(() => {
    const endpoint = document.querySelector('input[placeholder*="your-node"]');
    const token = document.querySelector('input[placeholder*="bearer"], input[placeholder*="token"], input[placeholder*="api key"]');
    r(JSON.stringify({fieldsRevealed: !!endpoint && !!token, endpointVal: endpoint?.value, testBtn: !!Array.from(document.querySelectorAll('button')).find(b => /test connection/i.test(b.innerText))}));
  }, 800));
})()

