import type { PinningProvider, PinResult, PinStatus, ProviderOptions, FetchFn } from './types';

/** Default timeout for all Kubo RPC requests — generous for large file pins */
const DEFAULT_TIMEOUT_MS = 10_000;

/**
 * PinningProvider implementation for Kubo RPC API (/api/v0/*).
 *
 * Talks directly to a Kubo node's HTTP API. Suitable for self-hosted
 * Kubo nodes or any IPFS node exposing the Kubo-compatible RPC interface.
 */
export class KuboProvider implements PinningProvider {
  private readonly endpoint: string;
  private readonly authToken?: string;
  private readonly fetchFn: FetchFn;
  private readonly timeoutMs: number;

  constructor(endpoint: string, authToken?: string, options?: ProviderOptions) {
    // Normalize: strip trailing slash
    this.endpoint = endpoint.replace(/\/+$/, '');
    this.authToken = authToken;
    // Bind the fallback: invoking native fetch as `this.fetchFn(...)` sets `this`
    // to the provider instance, which throws "Illegal invocation" in browsers
    // (Node's fetch is not this-sensitive, so only real browsers hit it).
    this.fetchFn = options?.fetchFn ?? globalThis.fetch.bind(globalThis);
    this.timeoutMs = options?.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  /**
   * Upload and pin data to the Kubo node.
   * Uses /api/v0/add with pin=true and cid-version=1 for CIDv1.
   */
  async pin(data: Uint8Array, _name?: string): Promise<PinResult> {
    const url = `${this.endpoint}/api/v0/add?pin=true&cid-version=1`;
    const formData = new FormData();
    // Pass typed array directly to Blob (never use .buffer to avoid offset issues)
    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
    formData.append('file', blob);

    const response = await this.fetchFn(url, {
      method: 'POST',
      body: formData,
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeoutMs),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Kubo add failed: ${response.status} - ${errorText}`);
    }

    // Kubo returns ndjson; for a single file, parse the first (only) line
    const text = await response.text();
    const result = JSON.parse(text) as { Hash: string; Size: string };
    return {
      cid: result.Hash,
      size: parseInt(result.Size, 10),
    };
  }

  /**
   * Remove a pin by CID.
   * Ignores "not pinned" errors for idempotency.
   */
  async unpin(cid: string): Promise<void> {
    const url = `${this.endpoint}/api/v0/pin/rm?arg=${encodeURIComponent(cid)}`;

    const response = await this.fetchFn(url, {
      method: 'POST',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeoutMs),
    });

    if (!response.ok) {
      const errorText = await response.text();
      // "not pinned" means already unpinned -- treat as success (idempotent)
      if (errorText.toLowerCase().includes('not pinned')) {
        return;
      }
      throw new Error(`Kubo unpin failed: ${response.status} - ${errorText}`);
    }
  }

  /**
   * Check pin status by CID.
   * Returns 'pinned' on success, 'failed' if the CID is not pinned.
   */
  async status(cid: string): Promise<PinStatus> {
    const url = `${this.endpoint}/api/v0/pin/ls?arg=${encodeURIComponent(cid)}`;

    try {
      const response = await this.fetchFn(url, {
        method: 'POST',
        headers: this.buildHeaders(),
        signal: AbortSignal.timeout(this.timeoutMs),
      });

      if (!response.ok) {
        return { cid, status: 'failed' };
      }

      return { cid, status: 'pinned' };
    } catch {
      return { cid, status: 'failed' };
    }
  }

  /**
   * Fetch pinned content by CID.
   * Returns the raw bytes of the content.
   */
  async get(cid: string): Promise<Uint8Array> {
    const url = `${this.endpoint}/api/v0/cat?arg=${encodeURIComponent(cid)}`;

    const response = await this.fetchFn(url, {
      method: 'POST',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeoutMs),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Kubo cat failed: ${response.status} - ${errorText}`);
    }

    return new Uint8Array(await response.arrayBuffer());
  }

  /** Build auth headers for Kubo requests */
  private buildHeaders(): Record<string, string> {
    if (this.authToken) {
      return { Authorization: `Basic ${this.authToken}` };
    }
    return {};
  }
}

import type { PinningProvider, PinResult, PinStatus, ProviderOptions, FetchFn } from './types';

/** Default timeout for all PSA requests — external service */
const DEFAULT_TIMEOUT_MS = 15_000;

/** PSA pin object from the Pinning Service API response */
interface PsaPinObject {
  requestid: string;
  status: 'queued' | 'pinning' | 'pinned' | 'failed';
  pin: {
    cid: string;
    name?: string;
  };
}

/** PSA list response */
interface PsaListResponse {
  count: number;
  results: PsaPinObject[];
}

/**
 * PinningProvider implementation for the IPFS Pinning Service API (PSA).
 *
 * PSA is a CID-reference-only protocol: it cannot accept raw data uploads.
 * Data must be uploaded to an IPFS node first, then the CID is submitted
 * to the pinning service for retrieval and pinning.
 *
 * Supports: Pinata, web3.storage, Filebase, and any PSA-compatible service.
 */
export class PsaProvider implements PinningProvider {
  private readonly endpoint: string;
  private readonly authToken: string;
  private readonly fetchFn: FetchFn;
  private readonly timeoutMs: number;

  constructor(endpoint: string, authToken: string, options?: ProviderOptions) {
    // Normalize: strip trailing slash
    this.endpoint = endpoint.replace(/\/+$/, '');
    this.authToken = authToken;
    // Bind the fallback: invoking native fetch as `this.fetchFn(...)` sets `this`
    // to the provider instance, which throws "Illegal invocation" in browsers
    // (Node's fetch is not this-sensitive, so only real browsers hit it).
    this.fetchFn = options?.fetchFn ?? globalThis.fetch.bind(globalThis);
    this.timeoutMs = options?.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  }

  /**
   * PSA cannot upload raw data. Always throws.
   * Use pinByCid() after uploading via CipherBox relay or a Kubo node.
   */
  async pin(_data: Uint8Array, _name?: string): Promise<PinResult> {
    throw new Error(
      'PsaProvider.pin() cannot upload raw data. Use pinByCid() after uploading via CipherBox relay or Kubo node.'
    );
  }

  /**
   * Pin a CID on the pinning service.
   * The service will retrieve the content from the IPFS network and pin it.
   */
  async pinByCid(
    cid: string,
    name?: string
  ): Promise<{ cid: string; status: PinStatus['status'] }> {
    const url = `${this.endpoint}/pins`;
    const body = {
      cid,
      name: name ?? `cipherbox-${Date.now()}`,
    };

    const response = await this.fetchFn(url, {
      method: 'POST',
      headers: this.buildHeaders({ 'Content-Type': 'application/json' }),
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(this.timeoutMs),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`PSA pin failed: ${response.status} - ${errorText}`);
    }

    const result = (await response.json()) as PsaPinObject;
    return {
      cid: result.pin.cid,
      status: result.status,
    };
  }

  /**
   * Remove a pin by CID.
   * PSA uses requestid for deletion, so we first list pins by CID
   * to find the requestid(s), then delete each one.
   */
  async unpin(cid: string): Promise<void> {
    // First, find the pin request(s) for this CID
    const listUrl = `${this.endpoint}/pins?cid=${encodeURIComponent(cid)}&status=pinned,pinning,queued`;

    const listResponse = await this.fetchFn(listUrl, {
      method: 'GET',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeoutMs),
    });

    if (!listResponse.ok) {
      const errorText = await listResponse.text();
      throw new Error(`PSA list for unpin failed: ${listResponse.status} - ${errorText}`);
    }

    const listResult = (await listResponse.json()) as PsaListResponse;

    // Delete each pin request by its requestid
    for (const pin of listResult.results) {
      const deleteUrl = `${this.endpoint}/pins/${encodeURIComponent(pin.requestid)}`;

      const deleteResponse = await this.fetchFn(deleteUrl, {
        method: 'DELETE',
        headers: this.buildHeaders(),
        signal: AbortSignal.timeout(this.timeoutMs),
      });

      if (!deleteResponse.ok) {
        const errorText = await deleteResponse.text();
        throw new Error(
          `PSA delete pin ${pin.requestid} failed: ${deleteResponse.status} - ${errorText}`
        );
      }
    }
  }

  /**
   * Check pin status by CID.
   * Queries the pinning service for the latest status of a CID.
   */
  async status(cid: string): Promise<PinStatus> {
    const url = `${this.endpoint}/pins?cid=${encodeURIComponent(cid)}&limit=1`;

    const response = await this.fetchFn(url, {
      method: 'GET',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(this.timeoutMs),
    });

    if (!response.ok) {
      return { cid, status: 'failed' };
    }

    const result = (await response.json()) as PsaListResponse;

    if (result.count === 0 || result.results.length === 0) {
      return { cid, status: 'failed' };
    }

    return {
      cid,
      status: result.results[0].status,
    };
  }

  /**
   * PSA does not support content retrieval. Always throws.
   * Use an IPFS gateway to fetch content by CID.
   */
  async get(_cid: string): Promise<Uint8Array> {
    throw new Error('PsaProvider does not support content retrieval. Use an IPFS gateway.');
  }

  /** Build auth headers with Bearer token */
  private buildHeaders(extra?: Record<string, string>): Record<string, string> {
    return {
      Authorization: `Bearer ${this.authToken}`,
      ...extra,
    };
  }
}

# Web App (`apps/web`) - Coding Guidelines

These guidelines are derived from recurring review issues across 16 PRs. Follow them to avoid common pitfalls caught by automated reviewers.

## Accessibility (a11y)

### ARIA roles require matching keyboard handlers

When adding `role` and `tabIndex={0}` to an element, you **must** also add the keyboard interaction contract for that role:

- **`role="button"`** requires `onKeyDown` handling Enter and Space:

  ```tsx
  onKeyDown={(e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleClick();
    }
  }}
  ```

- **`role="slider"`** requires `onKeyDown` handling ArrowLeft, ArrowRight (and optionally Home/End):

  ```tsx
  onKeyDown={(e) => {
    if (e.key === 'ArrowRight') { e.preventDefault(); seekForward(); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); seekBackward(); }
  }}
  ```

- If keyboard interaction is **not** needed, use a read-only role instead (e.g., `role="progressbar"` instead of `role="slider"`) and remove `tabIndex`.

### Focus-visible styles for all interactive elements

Every custom interactive element with `:hover` styles **must** also have `:focus-visible` styles so keyboard users can see focus:

```css
.my-button:hover {
  /* ... */
}
.my-button:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: 1px;
}
```

## Media Elements

### Always wrap `.play()` in try/catch

`HTMLMediaElement.play()` returns a Promise that rejects under autoplay policy or when interrupted by a new load. Never `await` it without error handling:

```tsx
try {
  await element.play();
  setIsPlaying(true);
} catch {
  // Browser blocked playback (autoplay policy / interruption)
}
```

### Sync state to new media elements on mount

When a dialog re-opens, a new `<audio>`/`<video>` element is created with default properties (volume=1.0, playbackRate=1.0), but React state retains the previous values. Apply stored state in `onLoadedMetadata`:

```tsx
const handleLoadedMetadata = useCallback(() => {
  const el = mediaRef.current;
  if (!el) return;
  el.volume = volume;
  el.playbackRate = speed;
  // ... set duration, dimensions, etc.
}, [volume, speed]);
```

## React Async Lifecycle

### Ref safety in async callbacks

Inside `async` functions that reference React refs, always re-check for null after each `await`. Never use non-null assertions (`!`) on refs in async code:

```tsx
const doc = pdfDocRef.current;
if (!doc) return;
const page = await doc.getPage(1);
// Re-check after await -- dialog may have closed
if (!canvasRef.current) return;
```

### Dialog close cleanup checklist

When a dialog/modal resets state on close, ensure **all** of these are cleaned up:

- All loading/error states
- All resolved data
- All timers (`clearTimeout`, `clearInterval`) via their refs
- All animation frames (`cancelAnimationFrame`)

### Debounce single-click when double-click exists

When an element handles both `onClick` (e.g., play/pause) and `onDoubleClick` (e.g., fullscreen), use a ~250ms timer to delay single-click and cancel it on double-click to prevent conflicting state changes.

## CSS

### Use modern color function notation

Always use the space-separated modern syntax. Never use legacy comma-separated `rgba()`:

```css
/* Bad */
background: rgba(0, 0, 0, 0.5);

/* Good */
background: rgb(0 0 0 / 50%);
```

## JSX / Biome Lint

### Wrap `//` text in JSX expressions

The terminal aesthetic uses `//` as decorative text, but Biome's `noCommentText` rule interprets it as a stray comment. Always wrap in braces:

```tsx
/* Bad */
<span>// encryption</span>

/* Good */
<span>{'// encryption'}</span>
```

## Binary Data

### Never use `.buffer` on Uint8Array for Blob construction

`Uint8Array.buffer` returns the **entire** underlying ArrayBuffer, which may be larger than the view. This causes silent data corruption, especially critical for encrypted payloads:

```tsx
/* Bad -- may include extra bytes */
new Blob([uint8array.buffer]);

/* Good -- pass the typed array directly */
new Blob([uint8array]);
```

